/**
 * The files a course provides beside the learner's own, per language, at the paths the step code
 * reaches them by. In Python and TypeScript they are the course's support modules exactly as the
 * browser runtime mounts them — generated `*_pb2.py`, hand-written helpers, the `.proto` sources
 * proto-loader reads — so they sit flat, where `import chat_pb2` and `loadSync('chat.proto')` find
 * them. Go, Scala and C++ import code that protoc generates and the course does not ship; for them
 * the tree carries the `.proto` source and, at the generated files' paths, honest stubs: a comment
 * saying who generates the file and what it declares, never fake generated code. Read-only in the
 * explorer: context, not an exercise.
 */
import type {Syntax} from './editor';
import type {Language, Problem} from './types';

export interface ProvidedFile {
  /** Path in the tree, relative to the course root, as the step code refers to it. */
  path: string;
  text: string;
  syntax: Syntax;
  /** One line above the viewer: where the file comes from and how the step code reaches it. */
  note: string;
}

/** `provided:<path>` — tab ids of provided files, beside the step ids of editable ones. */
export const providedId = (path: string): string => `provided:${path}`;
export const isProvidedId = (id: string): boolean => id.startsWith('provided:');
export const providedPath = (id: string): string => id.slice('provided:'.length);

const stem = (file: string): string => file.replace(/\.[^.]+$/, '');
const pascal = (name: string): string => name.replace(/(^|_)(\w)/g, (_, __, c: string) => c.toUpperCase());

/** What a `.proto` declares, for the stubs: its package, messages (with oneofs) and services with their rpcs. */
interface ProtoShape {
  pkg: string | null;
  messages: {name: string; oneofs: string[]}[];
  services: {name: string; rpcs: string[]}[];
}

function parseProto(text: string): ProtoShape {
  const pkg = /^\s*package\s+([\w.]+)\s*;/m.exec(text)?.[1] ?? null;
  const messages = [...text.matchAll(/^\s*message\s+(\w+)\s*\{([^}]*)\}/gm)].map(m => ({
    name: m[1],
    oneofs: [...m[2].matchAll(/oneof\s+(\w+)/g)].map(o => o[1]),
  }));
  const services = [...text.matchAll(/^\s*service\s+(\w+)\s*\{([\s\S]*?)^\}/gm)].map(s => ({
    name: s[1],
    rpcs: [...s[2].matchAll(/rpc\s+(\w+)\s*\(([^)]*)\)\s*returns\s*\(([^)]*)\)/g)].map(
      r => `rpc ${r[1]}(${r[2].trim()}) returns (${r[3].trim()})`,
    ),
  }));
  return {pkg, messages, services};
}

const describe = (shape: ProtoShape, comment: string): string[] => [
  `${comment} Messages: ${shape.messages
    .map(m => (m.oneofs.length > 0 ? `${m.name} (oneof ${m.oneofs.join(', ')})` : m.name))
    .join(', ')}`,
  ...shape.services.flatMap(s => [`${comment} Service ${s.name}:`, ...s.rpcs.map(r => `${comment}   ${r}`)]),
];

/** The import path the Go starters use for the generated package (`pb "chat/gen/chat"`), if they spell one out. */
const goImportPath = (problem: Problem, name: string): string | null => {
  for (const step of problem.steps) {
    const found = new RegExp(`"([\\w./-]+/gen/${name})"`).exec(step.code.go?.starter ?? '');
    if (found !== null) return found[1];
  }
  return null;
};

const pythonNote = (path: string): string => {
  const generated = /^(.*)_pb2(_grpc)?\.py$/.exec(path);
  if (generated !== null)
    return `Generated by protoc from ${generated[1]}.proto${
      generated[2] === undefined ? ' (messages)' : ' (service stubs)'
    }; the runtime mounts it beside your files, so \`import ${stem(path)}\` works as written.`;
  return `Provided by the course; the runtime mounts it beside your files, so \`import ${stem(
    path,
  )}\` works as written.`;
};

const typescriptNote = (path: string): string =>
  path.endsWith('.proto')
    ? `The contract @grpc/proto-loader parses at run time: \`protoLoader.loadSync('${path}')\` reads this file.`
    : `Provided by the course; the runtime mounts it beside your files, so \`import … from './${stem(
        path,
      )}'\` works as written.`;

const STUB_NOTE =
  'A stub in place of the generated file: the course does not ship generated code, so this lists what protoc would put here.';

/** The `.proto` and the generated-file stubs for one proto source, in `language`. */
function generated(problem: Problem, language: 'go' | 'scala' | 'cpp', file: string, text: string): ProvidedFile[] {
  const name = stem(file);
  const shape = parseProto(text);
  const src = language === 'scala' ? `src/main/protobuf/${file}` : `proto/${file}`;
  const source: ProvidedFile = {
    path: src,
    text,
    syntax: 'proto',
    note: `The source the generated files below come from; the course does not ship the generated code.`,
  };
  if (language === 'go') {
    const importPath = goImportPath(problem, name);
    const dir = `gen/${name}`;
    // A Go package clause is one identifier: `quotes.v1` becomes `quotesv1`, as buf and protoc-gen-go name it.
    const goPackage = (shape.pkg ?? name).replace(/\./g, '');
    const head = (tool: string): string[] => [
      `// Code generated by ${tool} from ${src}. DO NOT EDIT.`,
      `//`,
      `// The course does not ship the generated file; this stub lists what it declares.`,
      ...(importPath === null ? [] : [`// The step files import the package as "${importPath}".`]),
      `//`,
    ];
    return [
      source,
      {
        path: `${dir}/${name}.pb.go`,
        syntax: 'go',
        note: STUB_NOTE,
        text: [
          ...head('protoc-gen-go'),
          ...describe({...shape, services: []}, '//'),
          `//`,
          `// Regenerate: protoc -I proto --go_out=gen --go_opt=paths=source_relative ${src}`,
          ``,
          `package ${goPackage}`,
          ``,
        ].join('\n'),
      },
      ...(shape.services.length === 0
        ? []
        : [
            {
              path: `${dir}/${name}_grpc.pb.go`,
              syntax: 'go' as const,
              note: STUB_NOTE,
              text: [
                ...head('protoc-gen-go-grpc'),
                ...describe({...shape, messages: []}, '//').slice(1),
                ...shape.services.map(
                  s => `//   → ${s.name}Client, ${s.name}Server, Register${s.name}Server, Unimplemented${s.name}Server`,
                ),
                `//`,
                `// Regenerate: protoc -I proto --go-grpc_out=gen --go-grpc_opt=paths=source_relative ${src}`,
                ``,
                `package ${goPackage}`,
                ``,
              ].join('\n'),
            },
          ]),
    ];
  }
  if (language === 'scala') {
    const pkg = `${shape.pkg ?? name}.${name}`;
    const dir = `target/scala/src_managed/${pkg.replace(/\./g, '/')}`;
    const head = (what: string): string[] => [
      `// Generated by ScalaPB from ${src} (${what}). DO NOT EDIT.`,
      `//`,
      `// The course does not ship the generated file; this stub lists what it declares. The step files`,
      `// import it as ${pkg}.{…}.`,
      `//`,
    ];
    return [
      source,
      {
        path: `${dir}/${pascal(name)}Proto.scala`,
        syntax: 'scala',
        note: STUB_NOTE,
        text: [
          ...head('messages'),
          ...describe({...shape, services: []}, '//'),
          `// Each message is a case class with a companion (parseFrom, toByteArray, …).`,
          ``,
          `package ${pkg}`,
          ``,
        ].join('\n'),
      },
      ...shape.services.map(s => ({
        path: `${dir}/${s.name}Grpc.scala`,
        syntax: 'scala' as const,
        note: STUB_NOTE,
        text: [
          ...head('service'),
          `// Service ${s.name}:`,
          ...s.rpcs.map(r => `//   ${r}`),
          `//   → ${s.name}Grpc.${s.name} (the trait to implement), ${s.name}Grpc.${s.name}Stub, ${s.name}Grpc.bindService`,
          ``,
          `package ${pkg}`,
          ``,
        ].join('\n'),
      })),
    ];
  }
  const ns = shape.pkg?.replace(/\./g, '::') ?? name;
  const head = (what: string): string[] => [
    `// Generated by protoc${what === 'service' ? ' with grpc_cpp_plugin' : ''} from ${src} (${what}). DO NOT EDIT.`,
    `//`,
    `// The course does not ship the generated file; this stub lists what it declares. The step files`,
    `// include it as "${name}${what === 'service' ? '.grpc' : ''}.pb.h" (-Igen).`,
    `//`,
  ];
  return [
    source,
    {
      path: `gen/${name}.pb.h`,
      syntax: 'cpp',
      note: STUB_NOTE,
      text: [
        ...head('messages'),
        ...describe({...shape, services: []}, '//'),
        `// Each message is a class in namespace ${ns} with accessors, set_*(), SerializeToString(), ParseFromString().`,
        ``,
        `#pragma once`,
        ``,
      ].join('\n'),
    },
    ...(shape.services.length === 0
      ? []
      : [
          {
            path: `gen/${name}.grpc.pb.h`,
            syntax: 'cpp' as const,
            note: STUB_NOTE,
            text: [
              ...head('service'),
              ...describe({...shape, messages: []}, '//').slice(1),
              ...shape.services.map(
                s => `//   → ${ns}::${s.name}::Service, ${ns}::${s.name}::Stub, ${ns}::${s.name}::NewStub`,
              ),
              ``,
              `#pragma once`,
              ``,
            ].join('\n'),
          },
        ]),
  ];
}

// ---- helpers the steps import that only exist in Python and TypeScript -------------------------

/** Everything the step code in `language` says, starters and solutions, for scanning imports and uses. */
const allCode = (problem: Problem, language: Language): string =>
  problem.steps.map(s => `${s.code[language]?.starter ?? ''}\n${s.code[language]?.solution ?? ''}`).join('\n');

/** `Name.member` uses of an imported package or object across the step code, deduplicated, in order of appearance. */
const usesOf = (code: string, alias: string): string[] => {
  const seen = new Set<string>();
  for (const m of code.matchAll(new RegExp(`\\b${alias}\\.(\\w+)`, 'g'))) seen.add(m[1]);
  return [...seen];
};

/** The Python support module with this stem (`db` → `payments/db.py`), with what it defines. */
const pythonReference = (
  problem: Problem,
  name: string,
): {path: string; ts: string | null; defines: string[]} | null => {
  const want = name.toLowerCase().replace(/_/g, '');
  const entry = Object.entries(problem.support?.python ?? {}).find(
    ([path]) => !/_pb2(_grpc)?\.py$/.test(path) && stem(path.split('/').pop() ?? '').replace(/_/g, '') === want,
  );
  if (entry === undefined) return null;
  const [path, text] = entry;
  const defines = [...text.matchAll(/^(?:async\s+)?(?:def|class)\s+(\w+)/gm)]
    .map(m => m[1])
    .filter(n => !n.startsWith('_'));
  const tsPath = Object.keys(problem.support?.typescript ?? {}).find(
    p =>
      p.endsWith('.ts') &&
      stem(p.split('/').pop() ?? '')
        .replace(/_/g, '')
        .toLowerCase() === want,
  );
  return {path, ts: tsPath ?? null, defines};
};

const HELPER_NOTE = 'A stub for a helper the course ships only in Python and TypeScript; it says how the steps use it.';

/** The comment lines every helper stub opens with: what it is, where the reference is, what the steps use. */
const helperLines = (
  comment: string,
  what: string,
  reference: ReturnType<typeof pythonReference>,
  uses: string[],
): string[] => [
  `${comment} Provided by the course — not shipped in this language. ${what}`,
  ...(reference === null
    ? [`${comment} No Python or TypeScript counterpart is shipped either; the steps show what it has to offer.`]
    : [
        `${comment} The reference implementation is the Python helper ${reference.path}${
          reference.ts === null ? '' : ` (and ${reference.ts})`
        }, which the browser runtime mounts; open it in the Python or TypeScript tree.`,
        ...(reference.defines.length === 0 ? [] : [`${comment} It defines: ${reference.defines.join(', ')}`]),
      ]),
  ...(uses.length === 0 ? [] : [`${comment} The steps use: ${uses.join(', ')}`]),
];

/** Go: every `<module>/<pkg>` import that is not the generated package, as `<pkg>/<pkg>.go`. */
function goHelpers(problem: Problem): ProvidedFile[] {
  const code = allCode(problem, 'go');
  const modules = new Set([...code.matchAll(/"([\w.-]+)\/gen\/\w+"/g)].map(m => m[1]));
  const out = new Map<string, ProvidedFile>();
  for (const m of code.matchAll(/^\s*(?:(\w+)\s+)?"([\w./-]+)"/gm)) {
    const [, alias, path] = m;
    const mod = path.split('/')[0];
    if (!modules.has(mod) || path.includes('/gen/')) continue;
    const rel = path.slice(mod.length + 1);
    const pkg = rel.split('/').pop() ?? rel;
    const file = `${rel}/${pkg}.go`;
    if (out.has(file)) continue;
    const uses = usesOf(code, alias ?? pkg).map(u => `${alias ?? pkg}.${u}`);
    out.set(file, {
      path: file,
      syntax: 'go',
      note: HELPER_NOTE,
      text: [
        ...helperLines('//', `The step files import it as "${path}".`, pythonReference(problem, pkg), uses),
        ``,
        `package ${pkg}`,
        ``,
      ].join('\n'),
    });
  }
  return [...out.values()];
}

/** Scala: imports under the proto package's root (`payments.Db`, `feed.store._`) that are not the ScalaPB package. */
function scalaHelpers(problem: Problem, protoPackages: {pkg: string; name: string}[]): ProvidedFile[] {
  const code = allCode(problem, 'scala');
  const roots = new Set(protoPackages.map(p => p.pkg.split('.')[0]));
  const generatedPrefixes = protoPackages.map(p => `${p.pkg}.${p.name}`);
  const out = new Map<string, ProvidedFile>();
  for (const m of code.matchAll(/^\s*import\s+([\w.]+)/gm)) {
    const segments = m[1].split('.').filter(Boolean);
    if (!roots.has(segments[0]) || generatedPrefixes.some(g => m[1].startsWith(`${g}.`) || m[1] === g)) continue;
    // `a.b.C` names an object (file C.scala); `a.b._`-style wildcards (the trailing dot) name a package.
    const last = segments[segments.length - 1];
    const isObject = /^[A-Z]/.test(last);
    const dir = (isObject ? segments.slice(0, -1) : segments).join('/');
    const file = isObject ? `src/main/scala/${dir}/${last}.scala` : `src/main/scala/${dir}/package.scala`;
    if (out.has(file)) continue;
    const uses = isObject ? usesOf(code, last).map(u => `${last}.${u}`) : [];
    out.set(file, {
      path: file,
      syntax: 'scala',
      note: HELPER_NOTE,
      text: [
        ...helperLines(
          '//',
          `The step files import it as ${m[1].replace(/\.+$/, '')}${isObject ? '' : '._'}.`,
          pythonReference(problem, last),
          uses,
        ),
        ``,
        `package ${(isObject ? segments.slice(0, -1) : segments).join('.')}`,
        ``,
      ].join('\n'),
    });
  }
  return [...out.values()];
}

/** C++: every quoted include that is not a generated header — a step's own header, or a helper's. */
function cppHelpers(problem: Problem, generatedHeaders: Set<string>): ProvidedFile[] {
  const code = allCode(problem, 'cpp');
  const out = new Map<string, ProvidedFile>();
  for (const m of code.matchAll(/^\s*#include\s+"([^"]+)"/gm)) {
    const include = m[1];
    if (generatedHeaders.has(include) || out.has(include)) continue;
    const name = stem(include.split('/').pop() ?? include);
    const owner = problem.steps.findIndex(s => s.file === name);
    out.set(include, {
      path: include,
      syntax: 'cpp',
      note:
        owner < 0
          ? HELPER_NOTE
          : `The header of a step's own file: what the other steps include from ${name}.cpp. The course ships the .cpp.`,
      text: [
        ...(owner < 0
          ? helperLines('//', `The step files include it as "${include}".`, pythonReference(problem, name), [])
          : [
              `// Header for ${name}.cpp (step ${owner + 1}: ${
                problem.steps[owner].title
              }): what the later steps include`,
              `// from it. The course ships the .cpp as that step's file; the declarations follow its solution.`,
            ]),
        ``,
        `#pragma once`,
        ``,
      ].join('\n'),
    });
  }
  return [...out.values()];
}

/** Every file `language`'s starters may import that no step builds, in the order the course lists them. */
export function providedFiles(problem: Problem, language: Language): ProvidedFile[] {
  if (language === 'python' || language === 'typescript') {
    const note = language === 'python' ? pythonNote : typescriptNote;
    return Object.entries(problem.support?.[language] ?? {}).map(([path, text]) => ({
      path,
      text,
      syntax: path.endsWith('.proto') ? 'proto' : language,
      note: note(path),
    }));
  }
  // A kernel imports nothing the course provides.
  if (language === 'cuda') return [];
  // The .proto sources travel with the TypeScript support (proto-loader reads them at run time).
  const protos = Object.entries(problem.support?.typescript ?? {}).filter(([path]) => path.endsWith('.proto'));
  const fromProtos = protos.flatMap(([file, text]) => generated(problem, language, file, text));
  if (language === 'go') return [...fromProtos, ...goHelpers(problem)];
  if (language === 'scala')
    return [
      ...fromProtos,
      ...scalaHelpers(
        problem,
        protos.map(([file, text]) => ({pkg: parseProto(text).pkg ?? stem(file), name: stem(file)})),
      ),
    ];
  return [...fromProtos, ...cppHelpers(problem, new Set(fromProtos.map(f => f.path.replace(/^gen\//, ''))))];
}
